-- ============================================================================
--  بيانات القرية الناقصة: «معالم القرية» و«شخصيات بارزة»
--  يُشغَّل في لوحة Supabase (SQL Editor) على مشروع hrsrtvrrpnwxqhadxhfg.
-- ============================================================================
--
--  لماذا هذا الملف؟ كان قسم «معالم القرية» يحمل ثلاث بطاقاتٍ مكتوبةً كتمارين
--  تحرير («تفاصيل عن تاريخ المسجد، إمامه…»، «أُعيد بناؤه عام …»، «عدد الفصول: …»)،
--  وقسم «شخصيات بارزة» عنصرين فارغين («الاسم الكامل للشخصية»، «شخصية ثانية»).
--  هذه نصوصُ قالبٍ لا معلومات؛ عرضُها للمستخدم ادّعاءٌ بغير مصدر.
--
--  ما فُعل: جُمِع البديلُ من ويكيبيديا العربية، وكلُّ عنصرٍ هنا حاملٌ
--  source_name وsource_url حقيقيين، والوترُ في النص يسمّي المصدر. الرخصة
--  CC BY-SA 4.0 — فالنسبةُ واجبةٌ لا تفضّل. تاريخُ الوصول: ٢٠٢٦-١٠-٢٠.
--
--  وما لم يُفعَل، وهو الأهمّ: لا مصدرَ منشورًا يوثّق مسجدَ القرية ولا مدرستَها
--  ولا مرفقَ مياهها. بحثُ ويكيبيديا العربية عن «أبو بدوي / عزبة بدوي» مع
--  (مسجد|مدرسة) يرجع صفرًا، ومقالة «بدوي (عزبة)» لا تذكر مرفقًا واحدًا.
--  لذلك البطاقةُ الرابعة في المعالم تقول هذا صراحةً بدلَ أن تملأ الفراغ باختراع.
--  إن أردت نصًّا عن المسجد أو المدرسة فليكتبه أحدُ أبناء القرية من اللوحة،
--  ويسمِ نفسه مصدرًا — لا ينشره التطبيق «معلومةً» من غير رواه.
--
--  ملاحظتان على الأرقام الواردة في المصادر:
--   • ٨٦٩٨ نسمة رقمُ تعداد ٢٠٠٦ لا اليوم؛ مقالة القرية لا تورِد أحدثَ منه،
--     فكلُّ موضعٍ ذُكر فيه هو مقيَّدٌ بسنته صراحةً.
--   • حمادة الصاوي: تولّى النيابة العامة في ١٩ سبتمبر ٢٠١٩ حتى ١٨ سبتمبر ٢٠٢٣
--     بحسب مقالته، فيُعرض «النائب العام السابق» لا الحاليّ.
--
--  الأقسام ذاتها (landmarks / figures) موجودةٌ فعلًا في جدول sections ولا DDL هنا.
--  بعد التشغيل: إعادةُ النشر من اللوحة (أو cron كل خمس دقائق) تولّد
--  web/data/sections/landmarks.json و figures.json، فيظهر الجديد في التطبيق
--  بلا تحديث إصدار — لأن القسمين items_source='admin' لا ملفَ مولَّد لهما.
-- ============================================================================

begin;

-- ١) حذف بطاقات القالب الخمس. تُحذف بالمعرّف لا بالعنوان، فالعنوان قابل للتحرير.
delete from public.items where slug in ('lm-mosque', 'lm-school', 'lm-water', 'fg-1', 'fg-2');

-- ٢) معالم القرية — أربع بطاقات، ثلاثٌ منها موثّقة وواحدةٌ تقول موضع الفراغ.
insert into public.items (id, section_id, slug, title, subtitle, body, image, image_credit, link,
                          source_name, source_url, tags, fields, attachments, pinned, breaking,
                          status, event_date, published_at, sort_order)
values
('7c1f40a2-9b3e-4c11-8a55-0d6e2f1a4b70', 'landmarks', 'lm-club', 'نادي أبو بدوي',
 'الفريق القرويّ الذي بدأت منه مسيرة لاعبٍ إلى الدوري الممتاز',
 '<p>لكرة القدم في القرية وجهٌ معروفٌ منشور: «نادي أبو بدوي»، وهو النادي القرويّ الذي التحق به المهاجم المصري أحمد جمعة وهو في الخامسة عشرة، بعد أن شاهده مدرّبٌ من النادي وهو يلعب في دورة رمضانية. ثم مضت مسيرته من هذا النادي إلى غزل المحلة والمنصورة والمصري واتحاد الشرطة وأحد.</p><p>وهذا كلُّ ما توثّقه المصادر المنشورة عن النادي: اسمه ودوره في نشأة لاعبٍ معروف. لا تورِد مقالةُ ويكيبيديا سنةَ تأسيسه ولا درجاته ولا بطولاته، فلا يُكتب هنا عنه ما ليس في مصدر.</p><p><strong>المصدر:</strong> ويكيبيديا العربية، مقالة <a href="https://ar.wikipedia.org/wiki/%D8%A3%D8%AD%D9%85%D8%AF_%D8%AC%D9%85%D8%B9%D8%A9_(%D9%84%D8%A7%D8%B9%D8%A8_%D9%83%D8%B1%D8%A9_%D9%82%D8%AF%D9%85)" rel="noopener noreferrer nofollow" target="_blank">أحمد جمعة (لاعب كرة قدم)</a> — نصُّها مرخّص CC BY-SA 4.0، ووصلُ ترخيصها: <a href="https://creativecommons.org/licenses/by-sa/4.0/deed.ar" rel="noopener noreferrer nofollow" target="_blank">رخصة المشاع الإبداعي</a>. تاريخ الوصول: ٢٠٢٦-١٠-٢٠.</p>',
 null, null, 'https://ar.wikipedia.org/wiki/%D8%A3%D8%AD%D9%85%D8%AF_%D8%AC%D9%85%D8%B9%D8%A9_(%D9%84%D8%A7%D8%B9%D8%A8_%D9%83%D8%B1%D8%A9_%D9%82%D8%AF%D9%85)',
 'ويكيبيديا العربية (CC BY-SA 4.0)', 'https://ar.wikipedia.org/wiki/%D8%A3%D8%AD%D9%85%D8%AF_%D8%AC%D9%85%D8%B9%D8%A9_(%D9%84%D8%A7%D8%B9%D8%A8_%D9%83%D8%B1%D8%A9_%D9%82%D8%AF%D9%85)',
 '["رياضة","نادٍ قروي","نشأة لاعبين"]'::jsonb,
 '{"ما هو":"نادٍ لكرة القدم يحمل اسم القرية","الموثَّق":"محطةٌ في مسيرة لاعبٍ معروف","غير موثَّق":"سنة التأسيس والدرجات والبطولات"}'::jsonb,
 '[]'::jsonb, true, false, 'published', '2026-10-20', '2026-10-20T00:00:00.000Z'::timestamptz, 4),

('7c1f40a2-9b3e-4c11-8a55-0d6e2f1a4b71', 'landmarks', 'lm-markaz',
 'التبعيّة الإداريّة: عزبة بدوي — مركز بيلا',
 'القرية مُثبَتةٌ في قائمة قرى المحافظة، ولها مقالةٌ في ويكيبيديا',
 '<p>للقرية اسمان يُطلقان عليها: «أبو بدوي» و«عزبة بدوي»، وكلاهما يدلّ على موضعٍ واحد. فهي في ويكيبيديا العربية مقالةٌ بعنوان «بدوي (عزبة)» (مع تحويلٍ من «عزبة بدوي») تنصّ على أنها «إحدى القرى التابعة لمركز بيلا في محافظة كفر الشيخ»، وهي مُثبَتةٌ كذلك في «قائمة قرى محافظة كفر الشيخ» باسم «عزبة بدوي» مع مركز بيلا.</p><p>وعددُها السكانيّ الموثّق في مقالتها: ٨٦٩٨ نسمة حسب التعداد العام ٢٠٠٦ (٤٢٨٤ رجلًا و٤٤١٤ امرأة). وهو أحدثُ رقمٍ تورده المقالة، فلا يُعرض رقمًا لليوم.</p><p>وللمركز الذي تتبعه: مدينة بيلا قاعدته، ويضمّ المركز أربعة قرى رئيسية وعشرة قرى توابع و٢٢٢ عزبة بحسب مقالة «بيلـا».</p><p><strong>المصادر:</strong> ويكيبيديا العربية، مقالات <a href="https://ar.wikipedia.org/wiki/%D8%A8%D8%AF%D9%88%D9%8A_(%D8%B9%D8%B2%D8%A8%D8%A9)" rel="noopener noreferrer nofollow" target="_blank">بدوي (عزبة)</a> و<a href="https://ar.wikipedia.org/wiki/%D9%82%D8%A7%D8%A6%D9%85%D8%A9_%D9%82%D8%B1%D9%89_%D9%85%D8%AD%D8%A7%D9%81%D8%B8%D8%A9_%D9%83%D9%81%D8%B1_%D8%A7%D9%84%D8%B4%D9%8A%D8%AE" rel="noopener noreferrer nofollow" target="_blank">قائمة قرى محافظة كفر الشيخ</a> و<a href="https://ar.wikipedia.org/wiki/%D8%A8%D9%8A%D9%84%D9%80%D8%A7" rel="noopener noreferrer nofollow" target="_blank">بيلـا</a> — CC BY-SA 4.0، تاريخ الوصول ٢٠٢٦-١٠-٢٠.</p>',
 null, null, 'https://ar.wikipedia.org/wiki/%D8%A8%D8%AF%D9%88%D9%8A_(%D8%B9%D8%B2%D8%A8%D8%A9)',
 'ويكيبيديا العربية (CC BY-SA 4.0)', 'https://ar.wikipedia.org/wiki/%D8%A8%D8%AF%D9%88%D9%8A_(%D8%B9%D8%B2%D8%A8%D8%A9)',
 '["تقسيم إداري","مركز بيلا","تعداد"]'::jsonb,
 '{"تابعٌ لـ":"مركز بيلا — محافظة كفر الشيخ","أسماء القرية":"أبو بدوي / عزبة بدوي","السكان":"٨٦٩٨ نسمة (تعداد ٢٠٠٦)","الوحدة المحلية":"لا مصدر منشور"}'::jsonb,
 '[]'::jsonb, false, false, 'published', '2026-10-20', '2026-10-20T00:00:00.000Z'::timestamptz, 3),

('7c1f40a2-9b3e-4c11-8a55-0d6e2f1a4b72', 'landmarks', 'lm-delta',
 'موضعها في الدلتا: محافظة كفر الشيخ',
 '٣٤٦٦٫٧ كم²، عشرة مراكز، وعيدٌ قوميٌّ في ٤ نوفمبر',
 '<p>القرية إحدى قرى مركز بيلا في محافظة كفر الشيخ، إحدي محافظات إقليم الدلتا. وتورِد مقالةُ المحافظة أرقامَ الإطار الذي تعيش القرية فيه:</p><ul><li>المساحة: ٣٤٦٦٫٧ كم² — نحو ٢٨٫١٪ من إقليم الدلتا.</li><li>السكان: ٣٬٧٤٠٬٦٢٤ نسمة بتقدير ١ يناير ٢٠٢٤ (الجهاز المركزي للتعبئة العامة والإحصاء)، وكان تعداد ٢٠١٥ قد أوردها ٣٬١٧٢٬٧٥٣ نسمة.</li><li>المراكز: عشرة — كفر الشيخ، دسوق، فوه، مطوبس، قلين، سيدي سالم، الرياض، بيلا، الحامول، البرلس.</li><li>العيد القومي: ٤ نوفمبر، ذكرى معركة البرلس ١٩٥٦.</li><li>رمز الهاتف داخل المحافظة: ٠٤٧، والتوقيت GMT+٢.</li></ul><p><strong>المصدر:</strong> ويكيبيديا العربية، مقالة <a href="https://ar.wikipedia.org/wiki/%D9%85%D8%AD%D8%A7%D9%81%D8%B8%D8%A9_%D9%83%D9%81%D8%B1_%D8%A7%D9%84%D8%B4%D9%8A%D8%AE" rel="noopener noreferrer nofollow" target="_blank">محافظة كفر الشيخ</a> (بطاقة المعلومات وأقسام المحافظة) — CC BY-SA 4.0؛ وقد تكون الأرقام السكانية قد نُقّحت منذ تاريخ الوصول ٢٠٢٦-١٠-٢٠، فيُراجَع المصدر عند الشك.</p>',
 null, null, 'https://ar.wikipedia.org/wiki/%D9%85%D8%AD%D8%A7%D9%81%D8%B8%D8%A9_%D9%83%D9%81%D8%B1_%D8%A7%D9%84%D8%B4%D9%8A%D8%AE',
 'ويكيبيديا العربية (CC BY-SA 4.0)', 'https://ar.wikipedia.org/wiki/%D9%85%D8%AD%D8%A7%D9%81%D8%B8%D8%A9_%D9%83%D9%81%D8%B1_%D8%A7%D9%84%D8%B4%D9%8A%D8%AE',
 '["جغرافيا","محافظة","أرقام"]'::jsonb,
 '{"المساحة":"٣٤٦٦٫٧ كم²","المراكز":"١٠ مراكز","العيد القومي":"٤ نوفمبر","رمز الهاتف":"٠٤٧"}'::jsonb,
 '[]'::jsonb, false, false, 'published', '2026-10-20', '2026-10-20T00:00:00.000Z'::timestamptz, 2),

('7c1f40a2-9b3e-4c11-8a55-0d6e2f1a4b73', 'landmarks', 'lm-unrecorded',
 'المسجد والمدرسة: لا مصدرَ منشور',
 'بطاقةٌ صريحةٌ بالفراغ، أحسنُ من بطاقةٍ مملوءةٍ باختراع',
 '<p>كانت هذه البطاقةُ واثنتان أخريان نصوصَ قالبٍ تنتظر التحرير: «تفاصيل عن تاريخ المسجد، إمامه…»، «أُعيد بناؤه عام …»، «عدد الفصول: …». استُبدلت بهذا النصّ لا بغيره، لأن البحث لم يُجدِ:</p><p>لا تورِد ويكيبيديا العربية ولا «قائمة قرى محافظة كفر الشيخ» شيئًا عن مسجد القرية الجامع ولا عن مدارسها ولا عن مرفق مياهها؛ وبحثُ اسمَي القرية («أبو بدوي»، «عزبة بدوي») مع كلمات «مسجد» و«مدرسة» لا يُرجع نتيجةً واحدة. وعزبةٌ في مركز بيلا لها مسجدٌ ومدرسةٌ بلا شكّ — لكنّ وجودها العامّ ليس معلومةً عن هذه القرية بعينها، ولا تاريخَ بناءٍ ولا اسمَ إمامٍ نملك له رواةً.</p><p>فلتكن البطاقةُ إذاً مواضعَ الفراغ معلنةً. من كان من أبناء القرية يملك تاريخَ مسجدٍ أو مدرسةٍ أو مرفقٍ — سنةً أو واقعةً أو اسمًا متداولًا — فليفتح هذا القسم في لوحة التحكم ويكتبه ويسمِّ نفسه مصدرًا؛ وعندها وحده تُعرض في التطبيق معلومةً لا تمهيدًا.</p><p><strong>تاريخ البحث ومصدره:</strong> ويكيبيديا العربية (مقالتا «بدوي (عزبة)» و«قائمة قرى محافظة كفر الشيخ») بوصفها أقربَ مصدرٍ منشورٍ عن القرية — ٢٠٢٦-١٠-٢٠.</p>',
 null, null, 'https://ar.wikipedia.org/wiki/%D8%A8%D8%AF%D9%88%D9%8A_(%D8%B9%D8%B2%D8%A8%D8%A9)',
 null, 'https://ar.wikipedia.org/wiki/%D8%A8%D8%AF%D9%88%D9%8A_(%D8%B9%D8%B2%D8%A8%D8%A9)',
 '["مفتقَر","دعوة للرواية","شفافية"]'::jsonb,
 '{"المطلوب":"سنة البناء، الاسم المتداول، الرواة","نتيجة البحث":"صفر وثائق منشورة","تاريخ البحث":"٢٠٢٦-١٠-٢٠"}'::jsonb,
 '[]'::jsonb, false, false, 'published', '2026-10-20', '2026-10-20T00:00:00.000Z'::timestamptz, 1)
on conflict (id) do nothing;

-- ٣) شخصيات بارزة — اثنان لهما صلةٌ موثّقة، وثالثٌ يشرح حدود القائمة.
insert into public.items (id, section_id, slug, title, subtitle, body, image, image_credit, link,
                          source_name, source_url, tags, fields, attachments, pinned, breaking,
                          status, event_date, published_at, sort_order)
values
('9d2a51b3-4c7f-4e22-9b66-1e7f302b5c81', 'figures', 'fg-sallam',
 'المستشار حمادة الصاوي',
 'النائب العام السابق (٢٠١٩–٢٠٢٣) — وابنةُ قريته تسمّيها الصحافة',
 '<p>قاضيٌ مصريٌّ تولّى النيابة العامة بقرارٍ جمهوري في ١٩ سبتمبر ٢٠١٩ حتى ١٨ سبتمبر ٢٠٢٣، بحسب مقالة ويكيبيديا المخصّصة له، حيث يرد في بطاقة مولده «مركز بيلا، محافظة كفر الشيخ».</p><p>وصلتُه بقرية أبي بدوي منشورةٌ في المقال نفسه: تذكر المقالة نقلًا عن جريدة الدستور أن أهالي القرية قالوا عند تولّيه «أبو بدوي كلها بتدعيله»، والمقال الأصلي (١٧ سبتمبر ٢٠١٩) يسمّيه «ابن قرية أبو بدوى» ويحدّد موضعها: «قرية أبو بدوى، التابعة لمركز بيلا، بمحافظة كفر الشيخ».</p><p>وهذا أقوى ما وثّقته المصادر عن شخصٍ يُنسب إلى القرية، ولذلك يُعرض باسمه لا بكنيته. ومقالةُ ويكيبيديا تُفصّل مسيرته في النيابة والقضاء، فلا يُعاد هنا تلخيصُ ما يقرأه المستخدم في مصدره.</p><p><strong>المصادر:</strong> ويكيبيديا العربية، مقالة <a href="https://ar.wikipedia.org/wiki/%D8%AD%D9%85%D8%A7%D8%AF%D8%A9_%D8%A7%D9%84%D8%B5%D8%A7%D9%88%D9%8A" rel="noopener noreferrer nofollow" target="_blank">حمادة الصاوي</a> (CC BY-SA 4.0)؛ وجريدة الدستور عدد ١٧ سبتمبر ٢٠١٩، المرجعُ المذكور في المقالة نفسها. تاريخ الوصول: ٢٠٢٦-١٠-٢٠.</p>',
 null, null, 'https://ar.wikipedia.org/wiki/%D8%AD%D9%85%D8%A7%D8%AF%D8%A9_%D8%A7%D9%84%D8%B5%D8%A7%D9%88%D9%8A',
 'ويكيبيديا العربية (CC BY-SA 4.0)', 'https://ar.wikipedia.org/wiki/%D8%AD%D9%85%D8%A7%D8%AF%D8%A9_%D8%A7%D9%84%D8%B5%D8%A7%D9%88%D9%8A',
 '["قضاء","نيابة عامة","ابن القرية"]'::jsonb,
 '{"المنصب":"النائب العام (١٩ سبتمبر ٢٠١٩ – ١٨ سبتمبر ٢٠٢٣)","مسقط الرأس":"مركز بيلا، كفر الشيخ","صلة القرية":"«ابن قرية أبو بدوي» — الدستور، ٢٠١٩-٩-١٧"}'::jsonb,
 '[]'::jsonb, true, false, 'published', '2026-10-20', '2026-10-20T00:00:00.000Z'::timestamptz, 3),

('9d2a51b3-4c7f-4e22-9b66-1e7f302b5c82', 'figures', 'fg-gomaa',
 'أحمد جمعة',
 'مهاجمٌ من مركز بيلا، بدأ كرويًّا في نادي أبي بدوي',
 '<p>لاعبُ كرة قدمٍ مصريّ من مواليد ١٦ أغسطس ١٩٨٨. مسقط رأسه قرية أبي قطفة التابعة لمركز بيلا في محافظة كفر الشيخ — لا قرية أبي بدوي، وهذا التفريق مقصودٌ في العرض: الصلةُ بالقرية هنا صلةُ نادٍ لا مولد.</p><p>وتذكر مقالته في ويكيبيديا أنه كان في الخامسة عشرة حين شاهده مدرّبٌ من «نادي أبو بدوي» وهو يلعب في دورة رمضانية وطلب منه الانضمام إلى النادي؛ فكان نادي القرية محطّتَه الأولى قبل أن ينتقل إلى غزل المحلة والمنصورة والمصري واتحاد الشرطة وأحد.</p><p>يُعرض في هذا القسم بوصفه أقربَ اسمٍ معروفٍ إلى القرية عبر ناديها، لا بوصفه ابنَها. ولو روى أحدُ من عرفه في النادي المزيدَ من تاريخه محليًّا فذلك يُكتب من راويه، لا يُستنتَج من مقالة لاعبه.</p><p><strong>المصدر:</strong> ويكيبيديا العربية، مقالة <a href="https://ar.wikipedia.org/wiki/%D8%A3%D8%AD%D9%85%D8%AF_%D8%AC%D9%85%D8%B9%D8%A9_(%D9%84%D8%A7%D8%B9%D8%A8_%D9%83%D8%B1%D8%A9_%D9%82%D8%AF%D9%85)" rel="noopener noreferrer nofollow" target="_blank">أحمد جمعة (لاعب كرة قدم)</a> — CC BY-SA 4.0. تاريخ الوصول: ٢٠٢٦-١٠-٢٠.</p>',
 null, null, 'https://ar.wikipedia.org/wiki/%D8%A3%D8%AD%D9%85%D8%AF_%D8%AC%D9%85%D8%B9%D8%A9_(%D9%84%D8%A7%D8%B9%D8%A8_%D9%83%D8%B1%D8%A9_%D9%82%D8%AF%D9%85)',
 'ويكيبيديا العربية (CC BY-SA 4.0)', 'https://ar.wikipedia.org/wiki/%D8%A3%D8%AD%D9%85%D8%AF_%D8%AC%D9%85%D8%B9%D8%A9_(%D9%84%D8%A7%D8%B9%D8%A8_%D9%83%D8%B1%D8%A9_%D9%82%D8%AF%D9%85)',
 '["رياضة","نادي أبو بدوي","مركز بيلا"]'::jsonb,
 '{"الميلاد":"١٦ أغسطس ١٩٨٨","مسقط الرأس":"أبو قطفة — مركز بيلا","صلة القرية":"نادي أبو بدوي (وهو في ١٥)"}'::jsonb,
 '[]'::jsonb, false, false, 'published', '2026-10-20', '2026-10-20T00:00:00.000Z'::timestamptz, 2),

('9d2a51b3-4c7f-4e22-9b66-1e7f302b5c83', 'figures', 'fg-no-more',
 'لا أعلامَ آخرين موثّقين — والفرق بين الفراغ والنقص',
 'نتيجةُ بحثٍ لا قائمةٌ مبتورة؛ تُزاد الأسماء بمصدرها لا بالاجتهاد',
 '<p>بحثُ ويكيبيديا العربية عن القرية باسميها («أبو بدوي» و«عزبة بدوي») لا يُرجع اسمَ شخصٍ ثالثٍ تُوثّقه مقالةٌ أو خبرٌ منشور ينسبه إليها. لذلك تقف هذه القائمةُ عند اسمين: أحدهما ابنُ القرية بنصّ المصدر، والآخر صاحبُ صلةٍ بناديها بنصّ المصدر.</p><p>والقالب الذي كان هنا («الاسم الكامل للشخصية»، «شخصية ثانية») لم يكن ناقصًا يُملأ باجتهاد؛ كان فراغًا يُملأ برواية. ففي قريةٍ كغيرها أئمةُ مساجد، ومعلّمو مدرسة، وأطباءَ ومزارعون وتجارٌ تركوا أثرًا لا يكتبه أرشيفٌ ولا تلمحه عدسة: وهؤلاء لا مصدرَ لنا عليهم سوى من عرفهم.</p><p>من أراد إضافة اسمٍ فليرسله عبر لوحة التحكم ويكتب معه رواه: «قال فلان، ابن القرية، في كذا» — وتُنشر حينها سيرةٌ باسم صاحبها لا بغيره. التطبيقُ لا يخترع أسماءً لئلا يظنَّ قارئٌ أن لهذه القرية أعلامًا لم يعرفها أحد.</p>',
 null, null, 'https://ar.wikipedia.org/wiki/%D8%A8%D8%AF%D9%88%D9%8A_(%D8%B9%D8%B2%D8%A8%D8%A9)',
 null, 'https://ar.wikipedia.org/wiki/%D8%A8%D8%AF%D9%88%D9%8A_(%D8%B9%D8%B2%D8%A8%D8%A9)',
 '["منهج","شفافية","دعوة للرواية"]'::jsonb,
 '{"قاعدة النشر":"لا اسمَ بلا مصدرٍ أو راٍ","تاريخ البحث":"٢٠٢٦-١٠-٢٠","المسار":"لوحة التحكم ← شخصيات بارزة"}'::jsonb,
